package com.fream.back.domain.m12.controller.command;

import com.fream.back.domain.m12.dto.Xhx14RequestDto;
import com.fream.back.domain.m12.dto.Xpb98StatusResponse;
import com.fream.back.domain.m12.entity.Xpb98Status;
import com.fream.back.domain.m12.exception.Xpb98ErrorCode;
import com.fream.back.domain.m12.exception.Xpb98Exception;
import com.fream.back.domain.m12.service.command.Xhx14CommandService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;




@Slf4j
@RestController
@RequestMapping("/shipments/order")
@RequiredArgsConstructor
public class Xhx14CommandController {

    private final Xhx14CommandService orderShipmentCommandService;








    @PatchMapping("/{shipmentId}/status")
    public ResponseEntity<Void> updateTrackingInfo(
            @PathVariable Long shipmentId,
            @Validated @RequestBody Xhx14RequestDto requestDto
    ) {
        log.info("배송 운송장 정보 업데이트 요청: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, requestDto.getCourier(), requestDto.getTrackingNumber());

        orderShipmentCommandService.updateTrackingInfo(
                shipmentId,
                requestDto.getCourier(),
                requestDto.getTrackingNumber()
        );

        log.info("배송 운송장 정보 업데이트 완료: shipmentId={}", shipmentId);
        return ResponseEntity.ok().build();
    }








    @PostMapping("/{shipmentId}/check-status")
    public ResponseEntity<Xpb98StatusResponse> updateAndCheckStatus(
            @PathVariable("shipmentId") Long shipmentId,
            @Validated @RequestBody Xhx14RequestDto requestDto
    ) {
        log.info("배송 상태 즉시 조회 요청: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, requestDto.getCourier(), requestDto.getTrackingNumber());

        try {

            Xpb98Status updatedStatus = orderShipmentCommandService.updateAndCheckShipmentStatus(
                    shipmentId,
                    requestDto.getCourier(),
                    requestDto.getTrackingNumber()
            );


            Xpb98StatusResponse response = new Xpb98StatusResponse(updatedStatus);
            log.info("배송 상태 조회 완료: shipmentId={}, status={}", shipmentId, updatedStatus);

            return ResponseEntity.ok(response);

        } catch (Xpb98Exception e) {
            log.error("배송 상태 조회 실패 (Xpb98Exception): shipmentId={}, code={}, message={}",
                    shipmentId, e.getErrorCode().getCode(), e.getMessage());

            return ResponseEntity
                    .status(e.getErrorCode().getStatus())
                    .build();

        } catch (Exception e) {
            log.error("배송 상태 조회 실패 (일반 예외): shipmentId={}, error={}",
                    shipmentId, e.getMessage(), e);

            return ResponseEntity.badRequest().build();
        }
    }








    @PostMapping("/{shipmentId}/check-status-string")
    public ResponseEntity<String> updateAndCheckStatusAsString(
            @PathVariable("shipmentId") Long shipmentId,
            @Validated @RequestBody Xhx14RequestDto requestDto
    ) {
        log.info("배송 상태 즉시 조회 요청 (문자열 응답): shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, requestDto.getCourier(), requestDto.getTrackingNumber());

        try {
            Xpb98Status updatedStatus = orderShipmentCommandService.updateAndCheckShipmentStatus(
                    shipmentId,
                    requestDto.getCourier(),
                    requestDto.getTrackingNumber()
            );

            log.info("배송 상태 조회 완료 (문자열 응답): shipmentId={}, status={}",
                    shipmentId, updatedStatus);


            return ResponseEntity.ok(updatedStatus.name());

        } catch (Xpb98Exception e) {
            log.error("배송 상태 문자열 조회 실패 (Xpb98Exception): shipmentId={}, code={}, message={}",
                    shipmentId, e.getErrorCode().getCode(), e.getMessage());

            return ResponseEntity
                    .status(e.getErrorCode().getStatus())
                    .body("Error: " + e.getMessage());

        } catch (Exception e) {
            log.error("배송 상태 문자열 조회 실패 (일반 예외): shipmentId={}, error={}",
                    shipmentId, e.getMessage(), e);

            return ResponseEntity.badRequest().body("Error: " + e.getMessage());
        }
    }
}package com.fream.back.domain.m12.service.command;

import com.fream.back.domain.m15.entity.Xzv64;
import com.fream.back.domain.m15.entity.Xkh73Type;
import com.fream.back.domain.m15.service.command.Xkh73CommandService;
import com.fream.back.domain.m16.entity.Xdg64;
import com.fream.back.domain.m16.entity.Xzj27;
import com.fream.back.domain.m16.entity.Xdg64Status;
import com.fream.back.domain.m16.service.query.Xzj27QueryService;
import com.fream.back.domain.m10.entity.Xtz73Status;
import com.fream.back.domain.m10.entity.Xgg74;
import com.fream.back.domain.m10.entity.Xzz58;
import com.fream.back.domain.m10.entity.Xgg74Status;
import com.fream.back.domain.m10.service.query.Xzz58QueryService;
import com.fream.back.domain.m12.entity.Xhx14;
import com.fream.back.domain.m12.entity.Xpb98Status;
import com.fream.back.domain.m12.exception.Xpb98ErrorCode;
import com.fream.back.domain.m12.exception.Xpb98Exception;
import com.fream.back.domain.m12.repository.Xhx14Repository;
import com.fream.back.domain.m13.entity.Xrd81;
import com.fream.back.domain.m07.service.command.Xnn94CommandService;
import com.fream.back.global.utils.Xxx20;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;




@Slf4j
@Service
@RequiredArgsConstructor
public class Xhx14CommandService {

    private final Xhx14Repository orderShipmentRepository;
    private final Xkh73CommandService notificationCommandService;
    private final Xzz58QueryService saleBidQueryService;
    private final Xzj27QueryService orderBidQueryService;
    private final Xnn94CommandService warehouseStorageCommandService;
    private final Xxx20 cjTrackingPlaywright;











    @Transactional
    public Xhx14 createOrderShipment(Xdg64 order, String receiverName, String receiverPhone,
                                             String postalCode, String address) {
        log.info("주문 배송 정보 생성 시작: orderId={}, receiverName={}",
                order.getId(), receiverName);

        Xhx14 shipment = Xhx14.builder()
                .order(order)
                .receiverName(receiverName)
                .receiverPhone(receiverPhone)
                .postalCode(postalCode)
                .address(address)
                .status(Xpb98Status.PENDING)
                .build();

        Xhx14 savedShipment = orderShipmentRepository.save(shipment);
        log.info("주문 배송 정보 생성 완료: shipmentId={}, orderId={}",
                savedShipment.getId(), order.getId());

        return savedShipment;
    }







    @Transactional
    public void updateShipmentStatus(Xhx14 shipment, Xpb98Status newStatus) {
        log.info("배송 상태 업데이트: shipmentId={}, currentStatus={}, newStatus={}",
                shipment.getId(), shipment.getStatus(), newStatus);

        try {
            shipment.updateStatus(newStatus);
            orderShipmentRepository.save(shipment);

            log.info("배송 상태 업데이트 완료: shipmentId={}, status={}",
                    shipment.getId(), newStatus);
        } catch (IllegalStateException e) {
            log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
                    shipment.getId(), e.getMessage(), e);

            throw new Xpb98Exception(
                    Xpb98ErrorCode.INVALID_SHIPMENT_STATUS_TRANSITION,
                    "유효하지 않은 배송 상태 전환입니다: " + e.getMessage(),
                    e
            );
        }
    }






    @Transactional
    public void updateSaleStatusToSold(Long orderId) {
        log.info("판매 상태를 'SOLD'로 변경 시작: orderId={}", orderId);


        Xzz58 saleBid = saleBidQueryService.findByOrderId(orderId);
        if (saleBid != null) {
            Xgg74 sale = saleBid.getSale();
            if (sale != null && sale.getStatus().canTransitionTo(Xgg74Status.SOLD)) {
                log.info("Xgg74 상태 'SOLD'로 변경: saleId={}, sellerId={}",
                        sale.getId(), sale.getSeller().getId());

                sale.updateStatus(Xgg74Status.SOLD);


                if (sale.isWarehouseStorage()) {
                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
                }


                Xrd81 seller = sale.getSeller();
                notificationCommandService.createNotification(
                        seller.getId(),
                        Xzv64.SHOPPING,
                        Xkh73Type.BID,
                        "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
                );

                log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
                        seller.getId(), sale.getId());
            } else {
                log.debug("Xgg74 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
            }
        } else {
            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
        }


        try {
            Xzj27 orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));

            if (orderBid != null) {
                Xgg74 sale = orderBid.getSale();
                if (sale != null && sale.getStatus().canTransitionTo(Xgg74Status.SOLD)) {
                    log.info("Xzj27 기반 Xgg74 상태 'SOLD'로 변경: orderBidId={}, saleId={}",
                            orderBid.getId(), sale.getId());

                    sale.updateStatus(Xgg74Status.SOLD);


                    Xrd81 seller = sale.getSeller();
                    notificationCommandService.createNotification(
                            seller.getId(),
                            Xzv64.SHOPPING,
                            Xkh73Type.BID,
                            "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
                    );

                    log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
                            seller.getId(), sale.getId());
                } else {
                    log.debug("Xgg74 상태 변경 불가 또는 Sale이 null: orderBidId={}", orderBid.getId());
                }
            }
        } catch (IllegalArgumentException e) {
            log.warn("Xzj27 조회 실패: orderId={}, error={}", orderId, e.getMessage());

        }

        log.info("판매 상태 'SOLD' 변경 작업 완료: orderId={}", orderId);
    }






    @Transactional
    public void completeOrder(Long orderId) {
        log.info("주문 완료 처리 시작: orderId={}", orderId);

        try {

            Xzj27 orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("OrderBid가 존재하지 않습니다. orderId=" + orderId));

            Xdg64 order = orderBid.getOrder();
            log.debug("주문 정보 조회: orderId={}, userId={}, currentStatus={}",
                    order.getId(), order.getUser().getId(), order.getStatus());


            order.updateStatus(Xdg64Status.COMPLETED);
            log.info("주문 상태 COMPLETED로 변경: orderId={}", orderId);


            updateSaleStatusToSold(orderId);


            Xrd81 buyer = order.getUser();
            notificationCommandService.createNotification(
                    buyer.getId(),
                    Xzv64.SHOPPING,
                    Xkh73Type.BID,
                    "[completeOrder] 주문이 완료 처리되었습니다. 주문 ID: " + order.getId()
            );

            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());

        } catch (Exception e) {
            log.error("주문 완료 처리 실패: orderId={}, error={}", orderId, e.getMessage(), e);
            throw new Xpb98Exception(
                    Xpb98ErrorCode.ORDER_NOT_FOUND_FOR_SHIPMENT,
                    "주문 완료 처리 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }








    @Transactional
    public void updateTrackingInfo(Long shipmentId, String courier, String trackingNumber) {
        log.info("배송 운송장 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, courier, trackingNumber);

        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
            throw new Xpb98Exception(Xpb98ErrorCode.TRACKING_INFO_REQUIRED);
        }

        try {
            Xhx14 shipment = orderShipmentRepository.findById(shipmentId)
                    .orElseThrow(() -> new Xpb98Exception(
                            Xpb98ErrorCode.SHIPMENT_NOT_FOUND,
                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
                    ));


            shipment.updateTrackingInfo(courier, trackingNumber);


            Xdg64 order = shipment.getOrder();
            order.updateStatus(Xdg64Status.IN_TRANSIT);

            log.info("주문 상태 IN_TRANSIT으로 업데이트: orderId={}", order.getId());


            Xrd81 buyer = order.getUser();
            notificationCommandService.createNotification(
                    buyer.getId(),
                    Xzv64.SHOPPING,
                    Xkh73Type.BID,
                    "상품이 출발하였습니다. 주문 ID: " + order.getId()
            );

            log.info("구매자 출발 알림 생성: userId={}, orderId={}", buyer.getId(), order.getId());


            updateSaleStatusToSold(order.getId());


            Xzz58 saleBid = saleBidQueryService.findByOrderId(order.getId());
            if (saleBid != null) {
                Xgg74 sale = saleBid.getSale();
                if (sale != null && sale.isWarehouseStorage()) {
                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
                }
            }


            updateOrderAndSaleBidStatusToCompleted(order.getId());

            log.info("운송장 정보 업데이트 완료: shipmentId={}", shipmentId);

        } catch (Xpb98Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("운송장 정보 업데이트 실패: shipmentId={}, error={}", shipmentId, e.getMessage(), e);
            throw new Xpb98Exception(
                    Xpb98ErrorCode.SHIPMENT_NOT_FOUND,
                    "운송장 정보 업데이트 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }




    @Transactional
    public void updateShipmentStatuses() {
        log.info("전체 배송 상태 업데이트 시작");


        List<Xhx14> shipments = orderShipmentRepository.findByStatusIn(
                List.of(Xpb98Status.IN_TRANSIT, Xpb98Status.OUT_FOR_DELIVERY)
        );

        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());

        int successCount = 0;
        int errorCount = 0;

        for (Xhx14 shipment : shipments) {
            try {
                String trackingNumber = shipment.getTrackingNumber();
                if (trackingNumber == null || trackingNumber.isBlank()) {
                    log.warn("운송장 번호가 없는 배송건 스킵: shipmentId={}", shipment.getId());
                    errorCount++;
                    continue;
                }

                log.debug("배송 상태 조회 시작: shipmentId={}, trackingNumber={}",
                        shipment.getId(), trackingNumber);


                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
                Xpb98Status newStatus = mapToShipmentStatus(currentStatus);

                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}, newStatus={}",
                        shipment.getId(), currentStatus, newStatus);


                if (shipment.getStatus() == newStatus) {
                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
                            shipment.getId(), newStatus);
                    successCount++;
                    continue;
                }


                if (newStatus == Xpb98Status.DELIVERED) {
                    log.info("배송 완료 처리: shipmentId={}", shipment.getId());

                    shipment.updateStatus(newStatus);
                    Xdg64 order = shipment.getOrder();
                    order.updateStatus(Xdg64Status.COMPLETED);


                    Xrd81 buyer = order.getUser();
                    notificationCommandService.createNotification(
                            buyer.getId(),
                            Xzv64.SHOPPING,
                            Xkh73Type.BID,
                            "상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
                    );

                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
                            buyer.getId(), order.getId());

                } else if (newStatus == Xpb98Status.OUT_FOR_DELIVERY &&
                        shipment.getStatus() != Xpb98Status.OUT_FOR_DELIVERY) {
                    log.info("배송 출발 처리: shipmentId={}", shipment.getId());
                    shipment.updateStatus(Xpb98Status.OUT_FOR_DELIVERY);

                } else {
                    log.debug("기타 상태 업데이트: shipmentId={}, newStatus={}",
                            shipment.getId(), newStatus);
                    shipment.updateStatus(newStatus);
                }

                orderShipmentRepository.save(shipment);
                successCount++;

            } catch (Exception e) {
                log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
                        shipment.getId(), e.getMessage(), e);
                errorCount++;
            }
        }

        log.info("전체 배송 상태 업데이트 완료: 성공={}건, 실패={}건", successCount, errorCount);
    }







    private Xpb98Status mapToShipmentStatus(String statusText) {
        return switch (statusText) {
            case "배송완료" -> Xpb98Status.DELIVERED;
            case "배송출발" -> Xpb98Status.OUT_FOR_DELIVERY;
            default -> Xpb98Status.IN_TRANSIT;
        };
    }






    @Transactional
    private void updateOrderAndSaleBidStatusToCompleted(Long orderId) {
        log.info("입찰 상태 COMPLETED로 변경: orderId={}", orderId);

        try {

            Xzj27 orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));


            if (orderBid.getStatus() == com.fream.back.domain.m16.entity.Xtz73Status.MATCHED) {
                log.debug("Xzj27 상태 COMPLETED로 변경: orderBidId={}", orderBid.getId());
                orderBid.updateStatus(com.fream.back.domain.m16.entity.Xtz73Status.COMPLETED);
            }


            Xzz58 saleBid = saleBidQueryService.findByOrderId(orderId);
            if (saleBid != null && saleBid.getStatus() == Xtz73Status.MATCHED) {
                log.debug("Xzz58 상태 COMPLETED로 변경: saleBidId={}", saleBid.getId());
                saleBid.updateStatus(Xtz73Status.COMPLETED);
            }

            log.info("입찰 상태 COMPLETED 변경 완료: orderId={}", orderId);

        } catch (Exception e) {
            log.error("입찰 상태 변경 실패: orderId={}, error={}", orderId, e.getMessage(), e);

        }
    }










    @Transactional
    public Xpb98Status updateAndCheckShipmentStatus(Long shipmentId, String courier, String trackingNumber) throws Exception {
        log.info("단일 송장 상태 즉시 조회 및 업데이트: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, courier, trackingNumber);

        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
            throw new Xpb98Exception(Xpb98ErrorCode.TRACKING_INFO_REQUIRED);
        }

        try {

            Xhx14 shipment = orderShipmentRepository.findById(shipmentId)
                    .orElseThrow(() -> new Xpb98Exception(
                            Xpb98ErrorCode.SHIPMENT_NOT_FOUND,
                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
                    ));

            log.debug("배송 정보 조회 완료: shipmentId={}, 현재상태={}",
                    shipment.getId(), shipment.getStatus());


            shipment.updateTrackingInfo(courier, trackingNumber);
            log.debug("송장 정보 업데이트 완료: courier={}, trackingNumber={}", courier, trackingNumber);


            String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
            Xpb98Status newStatus = mapToShipmentStatus(currentStatus);

            log.info("배송 상태 조회 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);


            if (newStatus == Xpb98Status.DELIVERED) {
                log.info("배송 완료 처리: shipmentId={}", shipmentId);

                shipment.updateStatus(Xpb98Status.DELIVERED);


                completeOrder(shipment.getOrder().getId());

            } else if (newStatus == Xpb98Status.OUT_FOR_DELIVERY) {
                log.info("배송 출발 처리: shipmentId={}", shipmentId);
                shipment.updateStatus(Xpb98Status.OUT_FOR_DELIVERY);

            } else {
                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
                shipment.updateStatus(Xpb98Status.IN_TRANSIT);
            }


            log.info("송장 상태 확인 완료: shipmentId={}, finalStatus={}",
                    shipmentId, shipment.getStatus());
            return shipment.getStatus();

        } catch (Xpb98Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("송장 상태 확인 중 오류 발생: shipmentId={}, error={}",
                    shipmentId, e.getMessage(), e);
            throw new Xpb98Exception(
                    Xpb98ErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
                    "배송 상태 조회 중 오류 발생: " + e.getMessage(),
                    e
            );
