import com.fream.back.domain.m12.entity.Xpb98Status;
import com.fream.back.domain.m12.exception.Xpb98ErrorCode;
import com.fream.back.domain.m12.exception.Xpb98Exception;
import com.fream.back.domain.m12.repository.Xhx14Repository;
import com.fream.back.domain.m12.service.command.Xhx14CommandService;
import com.fream.back.global.utils.Xxx20;
import com.fream.back.global.utils.Xrk74;
import jakarta.persistence.EntityManagerFactory;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.SkipListener;
import org.springframework.batch.core.Step;
import org.springframework.batch.core.configuration.annotation.StepScope;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.batch.item.database.JpaItemWriter;
import org.springframework.batch.item.database.JpaPagingItemReader;
import org.springframework.batch.item.database.builder.JpaPagingItemReaderBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.transaction.PlatformTransactionManager;





@Slf4j
@Configuration
@RequiredArgsConstructor
public class Xqv91JobConfig {

    private final JobRepository jobRepository;
    private final PlatformTransactionManager transactionManager;
    private final EntityManagerFactory entityManagerFactory;

    private final Xhx14Repository orderShipmentRepository;
    private final Xkh73CommandService notificationService;
    private final Xhx14CommandService orderService;
    private final Xxx20 cjTrackingPlaywright;

    private static final int CHUNK_SIZE = 50;
    private static final int SKIP_LIMIT = 50;

    @Bean
    public Job updateShipmentStatusesJob() {
        log.info("배송 상태 업데이트 작업 구성");
        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
                .start(updateShipmentStatusesStep())
                .build();
    }

    @Bean
    public Step updateShipmentStatusesStep() {
        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);

        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
                .<Xhx14, Xhx14>chunk(CHUNK_SIZE, transactionManager)
                .reader(shipmentItemReader())
                .processor(new Xth19Processor(
                        playwrightBrowserManager(),
                        notificationService,
                        orderService
                ))
                .writer(shipmentJpaItemWriter())
                .faultTolerant()
                .skip(Exception.class)
                .skipLimit(SKIP_LIMIT)
                .listener(shipmentSkipListener())

                .listener(new Xmb36Listener(playwrightBrowserManager()))
                .build();
    }




    @Bean
    @StepScope
    public JpaPagingItemReader<Xhx14> shipmentItemReader() {
        log.debug("배송 상태 업데이트 ItemReader 구성");
        return new JpaPagingItemReaderBuilder<Xhx14>()
                .name("shipmentItemReader")
                .entityManagerFactory(entityManagerFactory)
                .pageSize(CHUNK_SIZE)
                .queryString("SELECT s FROM Xhx14 s WHERE s.status IN ('IN_TRANSIT','OUT_FOR_DELIVERY') AND s.trackingNumber IS NOT NULL")
                .build();
    }






    @Bean
    @StepScope
    public ItemProcessor<Xhx14, Xhx14> shipmentItemProcessor() {
        log.debug("배송 상태 업데이트 ItemProcessor 구성");


        return orderShipment -> {
            String trackingNumber = orderShipment.getTrackingNumber();
            Long shipmentId = orderShipment.getId();

            if (trackingNumber == null || trackingNumber.isBlank()) {
                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
                throw new Xpb98Exception(Xpb98ErrorCode.TRACKING_NUMBER_INVALID);
            }

            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
                    shipmentId, trackingNumber, orderShipment.getStatus());

            try {

                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);


                Xpb98Status newStatus = mapToShipmentStatus(currentStatus);
                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);


                if (orderShipment.getStatus() == newStatus) {
                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
                            shipmentId, newStatus);
                    return orderShipment;
                }


                if (newStatus == Xpb98Status.DELIVERED) {
                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
                            shipmentId, orderShipment.getOrder().getId());

                    orderShipment.updateStatus(Xpb98Status.DELIVERED);

                    orderService.completeOrder(orderShipment.getOrder().getId());

                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
                }
                else if (newStatus == Xpb98Status.OUT_FOR_DELIVERY) {
                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
                    orderShipment.updateStatus(Xpb98Status.OUT_FOR_DELIVERY);

                }
                else {
                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
                    orderShipment.updateStatus(Xpb98Status.IN_TRANSIT);
                }

                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
                return orderShipment;

            } catch (Exception e) {
                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
                        shipmentId, trackingNumber, e.getMessage(), e);


                if (!(e instanceof Xpb98Exception)) {
                    throw new Xpb98Exception(
                            Xpb98ErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
                            e
                    );
                }
                throw e;
            }
        };
    }








    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);

        try {

            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
            Document doc = Jsoup.connect(url).get();

            Elements rows = doc.select("tbody#statusDetail tr");
            if (rows.isEmpty()) {
                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
                throw new Xpb98Exception(
                        Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
                );
            }

            String status = rows.last().select("td").get(4).text();
            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
            return status;

        } catch (Exception e) {
            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);

            if (e instanceof Xpb98Exception) {
                throw e;
            }

            throw new Xpb98Exception(
                    Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
                    "배송 정보 조회 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }







    private Xpb98Status mapToShipmentStatus(String statusText) {
        return switch (statusText) {
            case "배송완료" -> Xpb98Status.DELIVERED;
            case "배송출발" -> Xpb98Status.OUT_FOR_DELIVERY;
            default -> Xpb98Status.IN_TRANSIT;
        };
    }




    @Bean
    @StepScope
    public JpaItemWriter<Xhx14> shipmentJpaItemWriter() {
        log.debug("배송 상태 업데이트 ItemWriter 구성");
        JpaItemWriter<Xhx14> writer = new JpaItemWriter<>();
        writer.setEntityManagerFactory(entityManagerFactory);
        return writer;
    }




    @Bean
    public SkipListener<Xhx14, Xhx14> shipmentSkipListener() {
        return new SkipListener<>() {
            @Override
            public void onSkipInProcess(Xhx14 item, Throwable t) {
                if (item != null) {
                    log.error("[Skip] 배송 상태 처리 스킵: shipmentId={}, trackingNumber={}, status={}, 사유={}",
                            item.getId(),
                            item.getTrackingNumber(),
                            item.getStatus(),
                            t.getMessage(),
                            t);
                } else {
                    log.error("[Skip] 배송 상태 처리 스킵: item=null, 사유={}", t.getMessage(), t);
                }
            }

            @Override
            public void onSkipInRead(Throwable t) {
                log.error("[SkipRead] 배송 정보 읽기 스킵: 사유={}", t.getMessage(), t);
            }

            @Override
            public void onSkipInWrite(Xhx14 item, Throwable t) {
                if (item != null) {
                    log.error("[SkipWrite] 배송 상태 저장 스킵: shipmentId={}, trackingNumber={}, status={}, 사유={}",
                            item.getId(),
                            item.getTrackingNumber(),
                            item.getStatus(),
                            t.getMessage(),
                            t);
                } else {
                    log.error("[SkipWrite] 배송 상태 저장 스킵: item=null, 사유={}", t.getMessage(), t);
                }
            }
        };
    }




    @Bean
    public Xrk74 playwrightBrowserManager() {
        log.debug("Playwright 브라우저 매니저 빈 생성");
        return new Xrk74();
    }
}package com.fream.back.domain.m12.config;

import com.fream.back.domain.m15.service.command.Xkh73CommandService;
import com.fream.back.domain.m12.entity.Xhx14;
import com.fream.back.domain.m12.entity.Xpb98Status;
import com.fream.back.domain.m12.exception.Xpb98ErrorCode;
import com.fream.back.domain.m12.exception.Xpb98Exception;
import com.fream.back.domain.m12.service.command.Xhx14CommandService;
import com.fream.back.global.utils.Xrk74;
import com.microsoft.playwright.Page;
import lombok.extern.slf4j.Slf4j;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;
import org.springframework.batch.item.ItemProcessor;





@Slf4j
public class Xth19Processor implements ItemProcessor<Xhx14, Xhx14> {

    private final Xrk74 browserManager;
    private final Xkh73CommandService notificationService;
    private final Xhx14CommandService orderService;

    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
    private static final int TIMEOUT_MS = 30000;








    public Xth19Processor(
            Xrk74 browserManager,
            Xkh73CommandService notificationService,
            Xhx14CommandService orderService
    ) {
        this.browserManager = browserManager;
        this.notificationService = notificationService;
        this.orderService = orderService;
    }








    @Override
    public Xhx14 process(Xhx14 orderShipment) throws Exception {
        String trackingNumber = orderShipment.getTrackingNumber();
        Long shipmentId = orderShipment.getId();

        if (trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
            throw new Xpb98Exception(Xpb98ErrorCode.TRACKING_NUMBER_INVALID);
        }

        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
                shipmentId, trackingNumber, orderShipment.getStatus());

        Page page = null;
        try {

            page = browserManager.newPage();
            if (page == null) {
                throw new Xpb98Exception(Xpb98ErrorCode.BROWSER_INITIALIZATION_ERROR);
            }


            page.setDefaultTimeout(TIMEOUT_MS);


            String url = TRACKING_URL_PREFIX + trackingNumber;
            log.debug("배송 조회 페이지로 이동: {}", url);
            page.navigate(url);


            log.debug("배송 상태 테이블 로드 대기");
            page.waitForSelector(STATUS_SELECTOR);


            String renderedHtml = page.content();
            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());


            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
            Xpb98Status newStatus = mapToShipmentStatus(statusText);

            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
                    shipmentId, statusText, newStatus);


            if (orderShipment.getStatus() == newStatus) {
                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
                        shipmentId, newStatus);
                return orderShipment;
            }


            if (newStatus == Xpb98Status.DELIVERED) {
                log.info("배송 완료 처리: shipmentId={}, orderId={}",
                        shipmentId, orderShipment.getOrder().getId());


                orderShipment.updateStatus(Xpb98Status.DELIVERED);


                orderService.completeOrder(orderShipment.getOrder().getId());
                notificationService.notifyShipmentCompleted(orderShipment.getOrder());

            } else if (newStatus == Xpb98Status.OUT_FOR_DELIVERY) {
                log.info("배송 출발 처리: shipmentId={}", shipmentId);
                orderShipment.updateStatus(Xpb98Status.OUT_FOR_DELIVERY);

            } else {
                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
                orderShipment.updateStatus(Xpb98Status.IN_TRANSIT);
            }

            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
                    shipmentId, orderShipment.getStatus());

            return orderShipment;

        } catch (Exception e) {
            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
                    shipmentId, trackingNumber, e.getMessage(), e);


            if (!(e instanceof Xpb98Exception)) {
                throw new Xpb98Exception(
                        Xpb98ErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
                        e
                );
            }
            throw e;
        } finally {

            if (page != null) {
                try {
                    page.close();
                    log.debug("페이지 리소스 해제 완료");
                } catch (Exception e) {
                    log.warn("페이지 닫기 실패: {}", e.getMessage());
                }
            }
        }
    }









    private String parseStatusFromHtml(String html, String trackingNumber) {
        try {
            Document doc = Jsoup.parse(html);
            Elements rows = doc.select(STATUS_SELECTOR);

            if (rows.isEmpty()) {
                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
                throw new Xpb98Exception(
                        Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
                );
            }


            String statusText = rows.last().select("td").get(4).text().trim();

            if (statusText.isEmpty()) {
                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
                throw new Xpb98Exception(
                        Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
                        "배송 상태 정보를 찾을 수 없습니다."
                );
            }

            return statusText;

        } catch (IndexOutOfBoundsException e) {
            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
            throw new Xpb98Exception(
                    Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
                    e
            );
        } catch (Exception e) {
            if (e instanceof Xpb98Exception) {
                throw (Xpb98Exception) e;
            }

            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
            throw new Xpb98Exception(
                    Xpb98ErrorCode.TRACKING_HTML_PARSE_ERROR,
                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
                    e
            );
        }
    }







    private Xpb98Status mapToShipmentStatus(String statusText) {
        return switch (statusText) {
            case "배송완료" -> Xpb98Status.DELIVERED;
            case "배송출발" -> Xpb98Status.OUT_FOR_DELIVERY;
            default -> Xpb98Status.IN_TRANSIT;
        };
    }
}

